function Get-Exp125ObservationQuality {
 param([int]$Failures,[int]$MaxConsecutiveFailures,[double]$MaximumValidSampleGapMilliseconds,[int]$InvalidJsonlRowCount=0,[bool]$CoversCoreStart=$true,[bool]$CoversCoreEnd=$true)
 if($Failures -eq 0 -and $MaxConsecutiveFailures -eq 0){return 'COMPLETE'}
 if($Failures -eq 1 -and $MaxConsecutiveFailures -eq 1 -and $InvalidJsonlRowCount -eq 0 -and $MaximumValidSampleGapMilliseconds -le 8000 -and $CoversCoreStart -and $CoversCoreEnd){return 'BOUNDED_TRANSIENT_LOSS'}
 return 'INVALID'
}
function Test-Exp125CollectorLifecycleSummary {
 param([object]$Summary,[int]$ActualExitCode)
 return $Summary.collectorStatus -eq 'COLLECTOR_STOPPED_BY_SIGNAL' -and $Summary.stopSignalObserved -eq $true -and [int]$Summary.processExitCode -eq 0 -and $ActualExitCode -eq 0
}
function New-Exp125CollectorCoverage {
 param([Parameter(Mandatory)][string]$RunId,[Parameter(Mandatory)][string]$JsonlPath,[Parameter(Mandatory)][string]$SummaryPath,[Parameter(Mandatory)][int]$CollectorDurationSeconds,[Parameter(Mandatory)][int]$IntervalMilliseconds,[Parameter(Mandatory)][string]$CollectorProcessStartedAt,[Parameter(Mandatory)][string]$CoreInvocationStartedAt,[Parameter(Mandatory)][string]$CoreInvocationCompletedAt,[Parameter(Mandatory)][string]$CollectorProcessCompletedAt,[Parameter(Mandatory)][string]$WaitReturnedFirstCoveringSampleAt)
 $lines=@(Get-Content -LiteralPath $JsonlPath -ErrorAction SilentlyContinue|Where-Object{$_.Trim()});$valid=@();$all=@();$invalid=0
 foreach($line in $lines){try{$s=$line|ConvertFrom-Json -ErrorAction Stop;$d=[DateTimeOffset]::Parse([string]$s.timestamp);$all+=$d;if($null-eq$s.failure-or[string]::IsNullOrWhiteSpace([string]$s.failure)){$valid+=$d}}catch{$invalid++}}
 $summary=Get-Content -LiteralPath $SummaryPath -Raw|ConvertFrom-Json;$failures=[int]$summary.failures;$maxConsecutive=[int]$summary.maxConsecutiveFailures;$maxGap=[double]$summary.maximumValidSampleGapMilliseconds
 $ordered=$true;for($i=1;$i-lt$all.Count;$i++){if($all[$i]-lt$all[$i-1]){$ordered=$false}}
 $start=[DateTimeOffset]::Parse($CoreInvocationStartedAt);$end=[DateTimeOffset]::Parse($CoreInvocationCompletedAt);$first=if($valid.Count){$valid[0]}else{$null};$last=if($valid.Count){$valid[$valid.Count-1]}else{$null};$firstCover=($valid|Where-Object{$_ -ge$end}|Select-Object -First 1);$coverStart=$null-ne$first-and$first-le$start;$coverEnd=$null-ne$firstCover-and$firstCover-ge$end;$waitAt=[DateTimeOffset]::Parse($WaitReturnedFirstCoveringSampleAt);if($null-eq$firstCover-or$waitAt-ne$firstCover){$coverEnd=$false}
 $quality=Get-Exp125ObservationQuality -Failures $failures -MaxConsecutiveFailures $maxConsecutive -MaximumValidSampleGapMilliseconds $maxGap -InvalidJsonlRowCount $invalid -CoversCoreStart $coverStart -CoversCoreEnd $coverEnd
 $status=if($valid.Count-gt1-and$invalid-eq0-and$ordered-and$coverStart-and$coverEnd-and$quality-in @('COMPLETE','BOUNDED_TRANSIENT_LOSS')){'COLLECTOR_COVERAGE_PASSED'}else{'COLLECTOR_COVERAGE_FAILED'}
 [ordered]@{runId=$RunId;collectorDurationSeconds=$CollectorDurationSeconds;intervalMilliseconds=$IntervalMilliseconds;collectorProcessStartedAt=$CollectorProcessStartedAt;collectorFirstValidSampleAt=if($first){$first.ToUniversalTime().ToString('o')}else{$null};coreInvocationStartedAt=$CoreInvocationStartedAt;coreInvocationCompletedAt=$CoreInvocationCompletedAt;collectorProcessCompletedAt=$CollectorProcessCompletedAt;collectorLastValidSampleAt=if($last){$last.ToUniversalTime().ToString('o')}else{$null};collectorFirstSampleCoveringCoreEndAt=if($coverEnd){$firstCover.ToUniversalTime().ToString('o')}else{$null};waitReturnedFirstCoveringSampleAt=$WaitReturnedFirstCoveringSampleAt;validSampleCount=$valid.Count;invalidSampleCount=$invalid;collectorFailures=$failures;maxConsecutiveFailures=$maxConsecutive;maximumValidSampleGapMilliseconds=$maxGap;allowedMaximumGapMilliseconds=8000;observationQuality=$quality;boundedTransientLossAccepted=($quality-eq'BOUNDED_TRANSIENT_LOSS');coversCoreStart=$coverStart;coversCoreEnd=$coverEnd;timestampsNonDecreasing=$ordered;coverageStatus=$status;failureType=if($status-eq'COLLECTOR_COVERAGE_PASSED'){$null}else{'COLLECTOR_COVERAGE_FAILED'}}
}
function Assert-Exp125CollectorCoverage([string]$CoveragePath){if((Get-Item $CoveragePath).PSIsContainer){$CoveragePath=Join-Path $CoveragePath 'pool/collector-coverage.json'};$c=Get-Content $CoveragePath -Raw|ConvertFrom-Json;if($c.coverageStatus-ne'COLLECTOR_COVERAGE_PASSED'-or-not$c.coversCoreStart-or-not$c.coversCoreEnd-or$c.invalidSampleCount-ne0-or$c.observationQuality-notin @('COMPLETE','BOUNDED_TRANSIENT_LOSS')){throw 'COLLECTOR_COVERAGE_FAILED'};if($c.observationQuality-eq'BOUNDED_TRANSIENT_LOSS'-and(-not$c.boundedTransientLossAccepted-or$c.collectorFailures-ne1-or$c.maxConsecutiveFailures-ne1-or[double]$c.maximumValidSampleGapMilliseconds-gt8000)){throw 'COLLECTOR_BOUNDED_TRANSIENT_LOSS_INVALID'};if([string]::IsNullOrWhiteSpace([string]$c.collectorFirstSampleCoveringCoreEndAt)-or$c.collectorFirstSampleCoveringCoreEndAt-ne$c.waitReturnedFirstCoveringSampleAt){throw 'COLLECTOR_POST_CORE_SAMPLE_MISSING'}}
